WITH base AS (SELECT id, supplier_name, country, city, rating, CASE WHEN country = 'US' THEN 1 ELSE 0 END is_us FROM suppliers WHERE city IS NOT NULL AND city IS DISTINCT FROM 'Bangkok'), latest AS (SELECT id, supplier_name, country, city, rating, is_us FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating NULLS LAST, id) AS rn FROM base) t WHERE rn = 1), scored AS (SELECT id, city, rating, is_us, LEAD(is_us) OVER w_running next_is_us, LAG(is_us) OVER w_running prev_is_us, LEAD(rating) OVER w_running next_rating, ROW_NUMBER() OVER w_running event_seq, LAST_VALUE(is_us, TRUE) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_is_us FROM latest WHERE is_us BETWEEN 56 AND 79 WINDOW w_running AS (PARTITION BY country ORDER BY rating, id)), cleaned AS (SELECT *, COALESCE(city, 'unassigned') city_filled FROM scored WHERE city IS NOT NULL AND rating < 3.2) SELECT id, rating, is_us, prev_is_us, city_filled FROM cleaned ORDER BY id NULLS FIRST
